def get_db():
    conn = sqlite3.connect(DB_FILE, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn


db = get_db()


def init_db():
    cur = db.cursor()

    cur.execute("""
        CREATE TABLE IF NOT EXISTS patients (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            age INTEGER DEFAULT 65,
            dob TEXT DEFAULT '',
            district TEXT DEFAULT '',
            state TEXT DEFAULT '',
            country TEXT DEFAULT '',
            language TEXT DEFAULT 'English',
            caregiver TEXT DEFAULT '',
            emergency TEXT DEFAULT '',
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS activities (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            game TEXT NOT NULL,
            domain TEXT NOT NULL,
            score REAL DEFAULT 0,
            accuracy REAL DEFAULT 0,
            response_time REAL DEFAULT 0,
            difficulty INTEGER DEFAULT 1,
            xp INTEGER DEFAULT 0,
            played_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS reminders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            kind TEXT NOT NULL,
            title TEXT NOT NULL,
            due TEXT NOT NULL,
            priority TEXT DEFAULT 'Normal',
            completed INTEGER DEFAULT 0,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS wellness (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            mood INTEGER DEFAULT 3,
            hydration INTEGER DEFAULT 0,
            activity INTEGER DEFAULT 0,
            note TEXT DEFAULT '',
            recorded_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS journal (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            category TEXT NOT NULL,
            text TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS doctor_chat (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            role TEXT NOT NULL,
            message TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS family_members (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            relation TEXT NOT NULL,
            name TEXT DEFAULT '',
            photo_base64 TEXT DEFAULT '',
            created_at TEXT NOT NULL
        )
    """)

    # One row per family-recall attempt (Doctor's Group Challenge or
    # Memory Flash Game). Powers the "My Journey" daily timeline.
    cur.execute("""
        CREATE TABLE IF NOT EXISTS family_recall_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            member_id INTEGER NOT NULL,
            relation TEXT DEFAULT '',
            name TEXT DEFAULT '',
            photo_base64 TEXT DEFAULT '',
            correct INTEGER DEFAULT 0,
            played_at TEXT NOT NULL
        )
    """)

    db.commit()

    # Older databases created before the family_points column existed.
    try:
        cur.execute("ALTER TABLE patients ADD COLUMN family_points INTEGER DEFAULT 0")
        db.commit()
    except Exception:
        pass

    # Older databases created before the patient-intake columns existed
    # (date of birth, district, state, country).
    for intake_column in ("dob", "district", "state", "country"):
        try:
            cur.execute(f"ALTER TABLE patients ADD COLUMN {intake_column} TEXT DEFAULT ''")
            db.commit()
        except Exception:
            pass

    # Create a demo patient automatically.
    count = cur.execute("SELECT COUNT(*) FROM patients").fetchone()[0]
    if count == 0:
        cur.execute(
            """INSERT INTO patients
               (name, age, language, caregiver, emergency, created_at)
               VALUES (?, ?, ?, ?, ?, ?)""",
            (
                "Srivastav Agarwal",
                72,
                "English",
                "Family Caregiver",
                "Emergency Contact",
                datetime.now().isoformat(timespec="seconds"),
            ),
        )
        db.commit()

    # Rename any pre-existing demo patient from earlier app versions.
    cur.execute(
        "UPDATE patients SET name = ? WHERE name = ?",
        ("Srivastav Agarwal", "Demo Elder"),
    )
    db.commit()


init_db()


