def query_df(sql, params=()):
    return pd.read_sql_query(sql, db, params=params)


def execute(sql, params=()):
    cur = db.cursor()
    cur.execute(sql, params)
    db.commit()
    return cur.lastrowid


def get_patients():
    return query_df("SELECT * FROM patients ORDER BY name")


def get_patient(pid):
    rows = query_df("SELECT * FROM patients WHERE id = ?", (pid,))
    return rows.iloc[0].to_dict() if not rows.empty else None


def now_text():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def get_time_greeting():
    """Return (greeting, emoji) based on the current hour of day.

    Retained for any future use, but the app-open greeting itself no
    longer varies by time of day — see render_app_open_greeting().
    """
    hour = datetime.now().hour
    if 5 <= hour < 12:
        return "Good morning", "🌅"
    elif 12 <= hour < 17:
        return "Good afternoon", "☀️"
    elif 17 <= hour < 21:
        return "Good evening", "🌇"
    else:
        return "Good night", "🌙"


def calculate_age(dob_value):
    """Calculate a whole-number age in years from a date of birth."""
    try:
        today = datetime.now().date()
        years = today.year - dob_value.year - (
            (today.month, today.day) < (dob_value.month, dob_value.day)
        )
        return max(years, 0)
    except Exception:
        return 65


