def render_app_splash_logo():
    """Show the MindBlossom logo exactly as designed, centered, on the
    very first screen the patient/caregiver sees when the app opens."""
    st.markdown(
        f"""
        <div style="text-align:center; padding: 6px 0 18px 0;">
            <img src="data:image/png;base64,{MINDBLOSSOM_LOGO_B64}"
                 style="width:min(78vw, 340px); max-width:340px; height:auto;
                        border-radius:50%;
                        box-shadow: 0 10px 34px rgba(60,40,120,.28);" />
        </div>
        """,
        unsafe_allow_html=True,
    )


def render_patient_intake_gate():
    if st.session_state.get("intake_complete"):
        return

    render_app_splash_logo()

    st.markdown(
        """
        <div class="hero" style="text-align:center;">
            <div class="pill">🧠 NER Care+</div>
            <h2>Welcome! Let's get to know you.</h2>
            <p>Please share a few details before we begin.</p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    with st.form("patient_intake_form", clear_on_submit=False):
        intake_name = st.text_input("Full Name *", placeholder="e.g. Anita Sharma")
        intake_dob = st.date_input(
            "Date of Birth *",
            value=datetime(1955, 1, 1),
            min_value=datetime(1900, 1, 1),
            max_value=datetime.now(),
            format="YYYY-MM-DD",
        )
        intake_district = st.text_input(
            "District (optional)", placeholder="e.g. Kamrup"
        )
        intake_state = st.text_input("State *", placeholder="e.g. Assam")
        intake_country = st.text_input("Country *", placeholder="e.g. India")

        intake_submitted = st.form_submit_button(
            "Continue ➜", use_container_width=True
        )

    if not intake_submitted:
        st.stop()

    if not intake_name.strip():
        st.error("Please enter your name to continue.")
        st.stop()
    if not intake_state.strip():
        st.error("Please enter your state to continue.")
        st.stop()
    if not intake_country.strip():
        st.error("Please enter your country to continue.")
        st.stop()

    new_patient_id = execute(
        """INSERT INTO patients
           (name, age, dob, district, state, country, language, caregiver, emergency, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (
            intake_name.strip(),
            calculate_age(intake_dob),
            intake_dob.isoformat(),
            intake_district.strip(),
            intake_state.strip(),
            intake_country.strip(),
            "English",
            "Family Caregiver",
            "Emergency Contact",
            datetime.now().isoformat(timespec="seconds"),
        ),
    )

    st.session_state.patient_id = new_patient_id
    st.session_state.intake_complete = True
    st.session_state.app_open_greeted = False
    st.rerun()


render_patient_intake_gate()


