# ================================================================
# AI DOCTOR CHAT — ULTRA PRO MAX
# ================================================================
#
# Two layers of intelligence power the AI Doctor:
#
#   1. An always-on emergency safety net (keyword based, instant, works
#      offline) that immediately flags anything that sounds like a
#      medical emergency, no matter what else is going on.
#
#   2. A full large-language-model "brain" (Anthropic's Claude API) that
#      can hold a rich, natural, ChatGPT/Claude-style conversation about
#      absolutely any health, memory, mood, sleep, appetite or
#      caregiving question, explain conditions and general medicine
#      information in plain language, and answer follow-up questions —
#      instead of only matching a fixed list of keywords.
#
# If no API key/internet is available, the app automatically falls back
# to the original built-in rule-based supportive assistant so it always
# keeps working offline.
#
# Even in "ultra pro max" mode, the AI Doctor still behaves the way a
# responsible real clinician would in a text chat: it explains things
# thoroughly, but it does not replace an in-person exam, does not hand
# out exact personal medication doses, and always pushes urgent/severe
# symptoms toward real emergency care.

DOCTOR_DISCLAIMER = (
    "I'm an AI assistant, not a real doctor - for anything urgent, "
    "severe, or worsening, please contact your caregiver, your real "
    "doctor, or emergency services right away."
)

EMERGENCY_KEYWORDS = [
    "chest pain", "can't breathe", "cannot breathe", "difficulty breathing",
    "slurred speech", "face drooping", "sudden weakness", "sudden numbness",
    "stroke", "unconscious", "collapsed", "severe bleeding", "heart attack",
    "suicidal", "want to die", "harm myself",
]

EMERGENCY_REPLY = (
    "🚨 This sounds like it could be a medical emergency. Please call "
    "your local emergency number or get to a hospital right now, and "
    "tell a family member or caregiver immediately. Please don't wait "
    "to see if it passes."
)


def is_emergency_message(text):
    text = (text or "").lower()
    return any(kw in text for kw in EMERGENCY_KEYWORDS)


# ----------------------------------------------------------------
# LLM configuration
# ----------------------------------------------------------------

DOCTOR_MODEL = "claude-sonnet-4-6"

DOCTOR_SYSTEM_PROMPT = """You are "AI Doctor" inside NER Care+, a cognitive
support app used by elderly users (often living with early-stage memory
difficulties) and their family caregivers.

Talk like a warm, knowledgeable, unhurried real doctor having a
conversation in clinic - not a search engine and not a wall of
disclaimers. You can discuss absolutely any health topic the person
raises: symptoms, medical conditions and how they usually work, general
information about medicines (what a class of medicine is for, common
side effects, why timing/adherence matters), sleep, mood, memory,
nutrition, exercise, hygiene, caregiving strategies, sexual health,
women's/men's health, chronic disease management, first aid, and
everyday worries. Give real, substantive, specific answers - the kind
of practical explanation a good GP would give - rather than vague
platitudes or refusing to engage.

House rules:
- Keep language simple, warm and short-sentenced; this audience may
  have memory or attention difficulties. Avoid jargon, or explain it
  immediately in plain words.
- You may explain what a medicine class generally does and typical
  dosing ranges as general medical knowledge, but do not tell this
  specific person to start, stop, or change a personal dose - that
  always needs their own doctor or pharmacist, since it depends on
  their exact health history.
- You do not have access to this person's test results, exam findings
  or full medical history, so frame conclusions as "this sounds like it
  could be..." rather than a certain diagnosis, and say when an
  in-person exam or test is the right next step.
- If the message describes anything that could be a medical emergency
  (e.g. chest pain, stroke symptoms, severe bleeding, can't breathe,
  suicidal thoughts, unconsciousness), lead with urging immediate
  emergency care - do not just give home remedies.
- Be encouraging and human. It's fine to reassure, to ask one gentle
  follow-up question, and to reference the app's own features (Family
  Recognition, Reminders, Wellness check-in, Journal) when relevant.
- Never mention that you are an "AI language model" repeatedly or add a
  disclaimer to every single message - a brief, natural reminder that
  you're not a substitute for their real doctor is enough once in a
  while, not every reply.
Keep most replies to 2-5 short sentences unless the person is asking
for a detailed explanation."""


def get_anthropic_api_key():
    """Look for an API key in Streamlit secrets, an env var, or a value
    the user pasted into Settings for this session."""
    key = st.session_state.get("anthropic_api_key", "").strip()
    if key:
        return key
    try:
        key = st.secrets.get("ANTHROPIC_API_KEY", "")
        if key:
            return key
    except Exception:
        pass
    return os.environ.get("ANTHROPIC_API_KEY", "")


def ai_doctor_llm_available():
    return ANTHROPIC_SDK_OK and bool(get_anthropic_api_key())


def call_ai_doctor_llm(chat_df, user_text, patient_name):
    """Send the recent conversation to Claude and return its reply text.
    Raises on any failure so the caller can fall back gracefully."""
    api_key = get_anthropic_api_key()
    client = anthropic.Anthropic(api_key=api_key)

    history = []
    for _, row in chat_df.tail(20).iterrows():
        role = "user" if row["role"] == "patient" else "assistant"
        history.append({"role": role, "content": row["message"]})
    history.append({"role": "user", "content": user_text})

    response = client.messages.create(
        model=DOCTOR_MODEL,
        max_tokens=600,
        system=DOCTOR_SYSTEM_PROMPT.replace(
            "this person", f"this person ({patient_name})"
        ),
        messages=history,
    )

    parts = [block.text for block in response.content if getattr(block, "type", "") == "text"]
    return "\n".join(parts).strip() or "I'm here - could you tell me a little more?"


