def init_life_memory_tables():
    cur = db.cursor()
    cur.execute("""CREATE TABLE IF NOT EXISTS life_jobs (
        id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL,
        role TEXT NOT NULL, workplace TEXT DEFAULT '', responsibilities TEXT DEFAULT '',
        years TEXT DEFAULT '', verified INTEGER DEFAULT 1, created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS life_dates (
        id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL,
        date_value TEXT NOT NULL, person_event TEXT NOT NULL, category TEXT DEFAULT 'Milestone',
        notes TEXT DEFAULT '', verified INTEGER DEFAULT 1, created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS life_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL,
        event_date TEXT NOT NULL, event_name TEXT NOT NULL, place TEXT DEFAULT '',
        notes TEXT DEFAULT '', verified INTEGER DEFAULT 1, created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS life_routines (
        id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL,
        routine_time TEXT NOT NULL, task TEXT NOT NULL, sequence_order INTEGER DEFAULT 1,
        notes TEXT DEFAULT '', verified INTEGER DEFAULT 1, created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS life_facts (
        id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL,
        category TEXT NOT NULL, title TEXT NOT NULL, detail TEXT DEFAULT '',
        verified INTEGER DEFAULT 1, created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS life_memory_attempts (
        id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL,
        game_type TEXT NOT NULL, correct INTEGER DEFAULT 0, total INTEGER DEFAULT 1,
        accuracy REAL DEFAULT 0, difficulty INTEGER DEFAULT 1, played_at TEXT NOT NULL)""")
    db.commit()

init_life_memory_tables()

def life_df(table, pid):
    if table not in {'life_jobs','life_dates','life_events','life_routines','life_facts'}:
        raise ValueError('Invalid Life-memory table')
    return query_df(f"SELECT * FROM {table} WHERE patient_id=? AND verified=1 ORDER BY id DESC", (pid,))

def life_level(pid):
    df=query_df("SELECT * FROM life_memory_attempts WHERE patient_id=? ORDER BY played_at DESC LIMIT 10",(pid,))
    if df.empty: return 1
    a=float(df.accuracy.mean())
    return min(5,max(1,2 if a>=70 else 1) if a<85 else min(5,3+int((a-85)//5)))

def life_log(pid, game, correct, total, difficulty):
    acc=100*correct/total if total else 0
    execute("INSERT INTO life_memory_attempts(patient_id,game_type,correct,total,accuracy,difficulty,played_at) VALUES(?,?,?,?,?,?,?)",(pid,game,correct,total,acc,difficulty,now_text()))
    try: log_game(pid, 'Life-memory • '+game, 'Life Memory', acc, acc, 5, difficulty)
    except Exception: pass
    return acc

def life_opts(values, correct, n=4):
    values=list(dict.fromkeys([str(x) for x in values if str(x).strip()]))
    if correct not in values: values.append(correct)
    if len(values)>n:
        others=[x for x in values if x!=correct]
        values=random.sample(others,n-1)+[correct]
    random.shuffle(values)
    return values

