# Fixed 10-member family roster requested for this patient.
FAMILY_ROLES = [
    "Himself (Patient)",
    "Wife",
    "Son",
    "Daughter-in-law",
    "Granddaughter",
    "Grandson",
    "Brother",
    "Daughter",
    "Brother's Son (Nephew)",
    "Brother's Daughter (Niece)",
]

FAMILY_POINTS_PER_CORRECT = 10


def ensure_family_members(pid):
    """Make sure this patient has exactly the 10 fixed family-role slots."""
    existing = query_df(
        "SELECT relation FROM family_members WHERE patient_id = ?", (pid,)
    )["relation"].tolist()

    for role in FAMILY_ROLES:
        if role not in existing:
            execute(
                """INSERT INTO family_members
                   (patient_id, relation, name, photo_base64, created_at)
                   VALUES (?, ?, ?, ?, ?)""",
                (pid, role, "", "", now_text()),
            )


def get_family_members(pid):
    ensure_family_members(pid)
    df = query_df(
        "SELECT * FROM family_members WHERE patient_id = ? ORDER BY id", (pid,)
    )
    return df


def save_family_member(member_id, name, photo_base64=None):
    if photo_base64 is not None:
        execute(
            "UPDATE family_members SET name = ?, photo_base64 = ? WHERE id = ?",
            (name, photo_base64, member_id),
        )
    else:
        execute(
            "UPDATE family_members SET name = ? WHERE id = ?",
            (name, member_id),
        )


def add_family_points(pid, points):
    execute(
        "UPDATE patients SET family_points = COALESCE(family_points, 0) + ? WHERE id = ?",
        (points, pid),
    )


def log_family_recall(pid, member, is_correct):
    """Record one family-recall attempt (right or wrong) so the
    'My Journey' page can show daily stars and recalled photos."""
    execute(
        """INSERT INTO family_recall_log
           (patient_id, member_id, relation, name, photo_base64, correct, played_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (
            pid,
            int(member["id"]),
            member.get("relation", ""),
            (member.get("name") or "").strip(),
            member.get("photo") or "",
            1 if is_correct else 0,
            now_text(),
        ),
    )


def get_journey_data(pid):
    """
    Build one entry per calendar day the patient attempted family
    recall, oldest first (Day 1 = the first day they ever played).
    Each entry has:
      day_number, date,
      stars   -> number of DIFFERENT family members correctly
                 recalled that day (1 member recalled = 1 star, etc.)
      members -> list of {relation, name, photo} for everyone they
                 correctly recalled that day, for the photo gallery.
    """
    df = query_df(
        "SELECT * FROM family_recall_log WHERE patient_id = ? ORDER BY played_at",
        (pid,),
    )
    if df.empty:
        return []

    df["date"] = df["played_at"].str.slice(0, 10)

    days = []
    for day_number, (date_val, group) in enumerate(
        df.groupby("date", sort=True), start=1
    ):
        correct = group[group["correct"] == 1]
        correct_unique = correct.drop_duplicates(subset=["member_id"], keep="first")

        members = [
            {
                "relation": row["relation"],
                "name": (row["name"] or "").strip(),
                "photo": row["photo_base64"],
            }
            for _, row in correct_unique.iterrows()
            if row["photo_base64"]
        ]

        days.append(
            {
                "day_number": day_number,
                "date": date_val,
                "stars": len(correct_unique),
                "members": members,
            }
        )

    return days


# ================================================================
# DOCTOR'S GROUP CHALLENGE
# (AI Doctor shows 8 family members together and asks "Who is this?"
#  one at a time. Correct answers earn praise, claps and a growing
#  row of stars. Wrong answers get no message at all - the correct
#  photo and the relationship name simply appear automatically.)
# ================================================================

GROUP_CHALLENGE_SIZE = 8


def build_doctor_group_round(pid):
    """
    Pick up to GROUP_CHALLENGE_SIZE family members that have a real
    uploaded photo, shuffle their order, and set up a fresh round.
    Returns None if there are not enough photos on file yet.
    """
    members = get_family_members(pid)
    ready = members[members["photo_base64"] != ""]

    if ready.empty:
        return None

    chosen = ready.sample(min(GROUP_CHALLENGE_SIZE, len(ready)), replace=False)
    chosen = chosen.sample(frac=1).reset_index(drop=True)  # shuffle order

    people = [
        {
            "id": int(row["id"]),
            "relation": row["relation"],
            "name": (row["name"] or "").strip(),
            "photo": row["photo_base64"],
            "result": None,  # None = not asked yet, True/False after answering
        }
        for _, row in chosen.iterrows()
    ]

    return {
        "people": people,
        "current": 0,
        "stars": 0,
        "phase": "asking",  # "asking" -> "feedback" -> ... -> "finished"
        "asked_aloud": False,
        "intro_spoken": False,
    }


