def sequence_game():
    st.markdown("## 🔢 Number Sequence Recall — 5 Levels")
    st.caption("Working memory • sequencing • mental manipulation")
    level = _cognitive_level_selector("sequence")

    configs = {
        1: {"length": 4, "low": 1, "high": 9, "task": "forward"},
        2: {"length": 5, "low": 1, "high": 20, "task": "forward"},
        3: {"length": 6, "low": 1, "high": 30, "task": "forward"},
        4: {"length": 7, "low": 1, "high": 50, "task": "reverse"},
        5: {"length": 8, "low": 1, "high": 99, "task": "reverse"},
    }
    cfg = configs[level]

    def build(lv):
        c = configs[lv]
        nums = [random.randint(c["low"], c["high"]) for _ in range(c["length"])]
        return {"nums": nums, "hidden": False}

    data, state_key = _new_cognitive_round("sequence", level, build)
    nums = data["nums"]
    task = cfg["task"]
    st.markdown(
        f"**Level {level}: {COGNITIVE_LEVELS[level]['name']}** • "
        f"Remember {len(nums)} numbers"
    )
    st.markdown(
        '<div class="feature-card" style="font-size:38px;text-align:center">'
        + " • ".join(map(str, nums)) + "</div>",
        unsafe_allow_html=True,
    )
    if not data["hidden"]:
        if st.button("🙈 Hide Numbers", key=f"seq_hide_{level}"):
            data["hidden"] = True
            st.rerun()
        return

    instruction = "Enter the numbers in the same order." if task == "forward" else "Enter the numbers in REVERSE order."
    st.info(instruction)
    ans = st.text_input("Your answer", key=f"seq_answer_{level}_{st.session_state.game_round}")
    if st.button("✅ Check Sequence", key=f"seq_check_{level}"):
        try:
            entered = [int(x) for x in ans.replace(",", " ").split()]
        except Exception:
            entered = []
        expected = nums if task == "forward" else list(reversed(nums))
        matches = sum(a == b for a, b in zip(entered, expected))
        accuracy = matches / len(expected) * 100
        exact = entered == expected
        _finish_cognitive_round(
            "Number Recall", level, accuracy, accuracy, len(expected), "Memory",
            "Excellent sequence memory!" if exact else
            f"You matched {matches}/{len(expected)} positions.", exact
        )
        del st.session_state[state_key]


