# 3. PATTERN / LOGICAL REASONING — 5 LEVELS
# ================================================================

def pattern_game():
    st.markdown("## 🔷 Pattern & Logical Reasoning — 5 Levels")
    st.caption("Pattern detection • prediction • flexible reasoning")
    level = _cognitive_level_selector("pattern")

    symbols = ["🔵", "🟢", "🟡", "🔴", "🟣", "🟠"]
    configs = {
        1: {"length": 6, "alphabet": 3, "rule": "repeat"},
        2: {"length": 8, "alphabet": 3, "rule": "repeat"},
        3: {"length": 10, "alphabet": 4, "rule": "alternating"},
        4: {"length": 12, "alphabet": 5, "rule": "cycle"},
        5: {"length": 14, "alphabet": 6, "rule": "cycle"},
    }
    cfg = configs[level]

    def build(lv):
        c = configs[lv]
        alphabet = symbols[:c["alphabet"]]
        if c["rule"] == "repeat":
            base_len = 2 if lv == 1 else 3
            base = [random.choice(alphabet) for _ in range(base_len)]
            pattern = (base * ((c["length"] // base_len) + 1))[:c["length"]]
        elif c["rule"] == "alternating":
            a, b = random.sample(alphabet, 2)
            pattern = [a if i % 2 == 0 else b for i in range(c["length"])]
        else:
            step = random.randint(1, len(alphabet) - 1) if len(alphabet) > 2 else 1
            start = random.randrange(len(alphabet))
            pattern = [alphabet[(start + i * step) % len(alphabet)] for i in range(c["length"])]
        hidden_count = 1 if lv <= 2 else (2 if lv <= 4 else 3)
        hidden_positions = sorted(random.sample(range(c["length"]), hidden_count))
        answers = {p: pattern[p] for p in hidden_positions}
        shown = ["❓" if i in hidden_positions else pattern[i] for i in range(c["length"])]
        return {"shown": shown, "answers": answers, "positions": hidden_positions, "alphabet": alphabet}

    data, state_key = _new_cognitive_round("pattern", level, build)
    st.markdown(f"**Level {level}: {COGNITIVE_LEVELS[level]['name']}**")
    st.markdown(
        '<div class="feature-card" style="font-size:34px;text-align:center;line-height:1.8">'
        + " &nbsp; ".join(data["shown"]) + "</div>", unsafe_allow_html=True
    )
    st.write("Fill every ❓ using the pattern rule.")
    answers = []
    for i, pos in enumerate(data["positions"]):
        answers.append(st.selectbox(
            f"Missing position {pos + 1}", data["alphabet"],
            key=f"pattern_ans_{level}_{i}_{st.session_state.game_round}"
        ))
    if st.button("🧩 Check Pattern", key=f"pattern_check_{level}"):
        expected = [data["answers"][p] for p in data["positions"]]
        matches = sum(a == b for a, b in zip(answers, expected))
        accuracy = matches / len(expected) * 100
        exact = matches == len(expected)
        _finish_cognitive_round(
            "Pattern Recognition", level, accuracy, accuracy,
            len(expected), "Pattern",
            "Outstanding pattern reasoning!" if exact else
            f"You solved {matches}/{len(expected)} missing positions.", exact
        )
        if not exact:
            st.write("Correct pattern answers:", " • ".join(expected))
        del st.session_state[state_key]


