def attention_game():
    st.markdown("## 🎯 Attention & Inhibition Challenge — 5 Levels")
    st.caption("Selective attention • sustained attention • inhibition")
    level = _cognitive_level_selector("attention")

    configs = {
        1: {"items": 24, "targets": 1, "symbols": ["⭐", "⭕", "🔺"]},
        2: {"items": 32, "targets": 1, "symbols": ["⭐", "⭕", "🔺", "🟦"]},
        3: {"items": 40, "targets": 2, "symbols": ["⭐", "⭕", "🔺", "🟦", "🍀"]},
        4: {"items": 52, "targets": 2, "symbols": ["⭐", "⭕", "🔺", "🟦", "🍀", "❤️"]},
        5: {"items": 64, "targets": 2, "symbols": ["⭐", "⭕", "🔺", "🟦", "🍀", "❤️", "🌙"]},
    }
    cfg = configs[level]

    def build(lv):
        c = configs[lv]
        targets = random.sample(c["symbols"], c["targets"])
        grid = [random.choice(c["symbols"]) for _ in range(c["items"])]
        # Guarantee each target appears at least once.
        for i, target in enumerate(targets):
            grid[i] = target
        random.shuffle(grid)
        return {"grid": grid, "targets": targets}

    data, state_key = _new_cognitive_round("attention", level, build)
    target_text = " + ".join(data["targets"])
    st.markdown(f"**Level {level}: {COGNITIVE_LEVELS[level]['name']}**")
    st.info(f"Count ONLY these target symbols: **{target_text}**")
    st.markdown(
        '<div class="feature-card" style="font-size:28px;line-height:2;text-align:center">'
        + " ".join(data["grid"]) + "</div>", unsafe_allow_html=True
    )

    expected = sum(1 for x in data["grid"] if x in data["targets"])
    answer = st.number_input(
        "How many target symbols did you see?",
        min_value=0, max_value=len(data["grid"]), value=0, step=1,
        key=f"attention_answer_{level}_{st.session_state.game_round}"
    )
    if st.button("🔎 Check Attention", key=f"attention_check_{level}"):
        error = abs(int(answer) - expected)
        accuracy = max(0.0, 100.0 - error * (12 if level < 4 else 10))
        exact = int(answer) == expected
        _finish_cognitive_round(
            "Attention Count", level, accuracy, accuracy, len(data["grid"]), "Attention",
            "Excellent selective attention!" if exact else
            f"Correct count: {expected}. You were off by {error}.", exact
        )
        del st.session_state[state_key]


