# 5. DAILY ROUTINE / EXECUTIVE FUNCTION — 5 LEVELS
# ================================================================

def routine_game():
    st.markdown("## 🏡 Daily Routine & Executive Function — 5 Levels")
    st.caption("Sequencing • planning • working memory • everyday reasoning")
    level = _cognitive_level_selector("routine")

    base = [
        "Wake up", "Brush teeth", "Drink water", "Get dressed",
        "Have breakfast", "Light exercise", "Rest"
    ]
    level_sets = {
        1: base[:4],
        2: base[:5],
        3: base[:6],
        4: base,
        5: base + ["Prepare for tomorrow", "Relax before sleep"],
    }
    routines = level_sets[level]

    def build(lv):
        expected = level_sets[lv][:]
        shuffled = expected[:]
        random.shuffle(shuffled)
        return {"expected": expected, "shuffled": shuffled}

    data, state_key = _new_cognitive_round("routine", level, build)
    st.markdown(
        f"**Level {level}: {COGNITIVE_LEVELS[level]['name']}** • "
        f"Arrange {len(data['expected'])} activities"
    )
    st.info("Select the activities in the order that makes the most sensible daily sequence.")

    selected = st.multiselect(
        "Choose in order",
        data["shuffled"],
        key=f"routine_answer_{level}_{st.session_state.game_round}"
    )
    if st.button("🏡 Check Routine", key=f"routine_check_{level}"):
        expected = data["expected"]
        # Position-based scoring plus a small credit for correct adjacent ordering.
        position_matches = sum(a == b for a, b in zip(selected, expected))
        if len(selected) > 1:
            positions = {item: i for i, item in enumerate(expected)}
            chosen_positions = [positions[x] for x in selected]
            adjacent = sum(
                chosen_positions[i] < chosen_positions[i + 1]
                for i in range(len(chosen_positions) - 1)
            )
            order_accuracy = adjacent / (len(chosen_positions) - 1) * 100
        elif len(selected) == 1:
            order_accuracy = 60.0
        else:
            order_accuracy = 0.0
        position_accuracy = position_matches / len(expected) * 100
        accuracy = round((position_accuracy * 0.65) + (order_accuracy * 0.35), 1)
        exact = selected == expected
        _finish_cognitive_round(
            "Daily Routine", level, accuracy, accuracy, len(expected), "Routine",
            "Wonderful planning and routine recall!" if exact else
            f"Good practice — {position_matches}/{len(expected)} activities were in the exact position.", exact
        )
        del st.session_state[state_key]


