EXTRA_EMOTIONS = ["Happy", "Calm", "Surprised", "Sad"]


def _family_rows(pid):
    return get_family_members(pid)


def _ready_family(pid):
    df = _family_rows(pid)
    return df[df["photo_base64"].fillna("") != ""].copy()


def _member_display(row):
    name = (row.get("name") or "").strip()
    rel = (row.get("relation") or "").strip()
    return name if name else rel


def _normalize_answer(value):
    return " ".join(str(value or "").strip().lower().split())


def _family_game_result(pid, game, score, accuracy, difficulty=1, response_time=5):
    return log_game(pid, game, "Recognition", score, accuracy, response_time, difficulty)


def _extra_photos(pid, member_id=None):
    if member_id is None:
        return query_df("SELECT * FROM family_extra_photos WHERE patient_id=? ORDER BY id", (pid,))
    return query_df("SELECT * FROM family_extra_photos WHERE patient_id=? AND member_id=? ORDER BY id", (pid, member_id))


def _all_member_photo_pool(pid):
    """Primary + additional photos, always tied to a verified member."""
    rows = []
    members = _ready_family(pid)
    for _, r in members.iterrows():
        rows.append({
            "member_id": int(r["id"]),
            "relation": r["relation"],
            "name": (r["name"] or "").strip(),
            "photo": r["photo_base64"],
            "source": "primary",
        })
        extras = _extra_photos(pid, int(r["id"]))
        for _, x in extras.iterrows():
            rows.append({
                "member_id": int(r["id"]),
                "relation": r["relation"],
                "name": (r["name"] or "").strip(),
                "photo": x["photo_base64"],
                "source": "extra",
                "label": x["label"],
            })
    return rows


def _data_url_bytes(data_url):
    if not data_url:
        return b""
    try:
        return base64.b64decode(data_url.split(",", 1)[1])
    except Exception:
        return b""


def _choice_labels(rows):
    return [_member_display(r) for r in rows]


def _adaptive_choice_count(pid):
    level = adaptive_difficulty(pid, "Recognition")
    return max(4, min(8, 3 + level)), level


def _start_round_if_needed(key, builder):
    if key not in st.session_state or st.session_state[key] is None:
        st.session_state[key] = builder()
    return st.session_state[key]


