def game_find_right_face(pid):
    st.markdown("### 1️⃣ Find the Right Face")
    members = _ready_family(pid)
    if len(members) < 2:
        st.info("Upload at least 2 family photos to play.")
        return
    choices_n, level = _adaptive_choice_count(pid)
    key = "frg_find_face_round"
    if st.button("🔄 New face challenge", key="new_find_face") or st.session_state.get(key) is None:
        target = members.sample(1).iloc[0]
        others = members[members["id"] != target["id"]]
        n = min(choices_n - 1, len(others))
        choices = pd.concat([pd.DataFrame([target]), others.sample(n)]).sample(frac=1).reset_index(drop=True)
        st.session_state[key] = {"target": int(target["id"]), "choices": choices[["id","name","relation","photo_base64"]].to_dict("records"), "answered": False}
    r = st.session_state[key]
    target_row = members[members["id"] == r["target"]].iloc[0]
    st.markdown(f"**Target:** Who is **{_member_display(target_row)}**? Find the matching face.")
    cols = st.columns(min(4, len(r["choices"])))
    picked = None
    for i, ch in enumerate(r["choices"]):
        with cols[i % len(cols)]:
            st.image(ch["photo_base64"], use_container_width=True)
            if st.button(f"Choose {i+1}", key=f"find_face_pick_{i}"):
                picked = ch
    if picked is not None and not r["answered"]:
        ok = int(picked["id"]) == r["target"]
        r["answered"] = True
        if ok:
            _family_game_result(pid, "Find the Right Face", 100, 100, level, 5)
            add_family_points(pid, FAMILY_POINTS_PER_CORRECT)
            celebration("Wonderful! You found the right face!")
            st.success("⭐ Correct!")
        else:
            _family_game_result(pid, "Find the Right Face", 0, 0, level, 6)
            st.info(f"Good effort. The target was {_member_display(target_row)}.")
        st.rerun()


