def game_same_person(pid):
    st.markdown("### 2️⃣ Same Person, Different Time")
    pool = _all_member_photo_pool(pid)
    grouped = {}
    for item in pool:
        grouped.setdefault(item["member_id"], []).append(item)
    pairs = []
    for mid, items in grouped.items():
        if len(items) >= 2:
            pairs.append((True, items[0], items[1]))
    ids = list(grouped)
    if len(ids) >= 2:
        a, b = random.sample(ids, 2)
        pairs.append((False, random.choice(grouped[a]), random.choice(grouped[b])))
    if not pairs:
        st.info("Add at least two photos for the same family member in 🗂️ Verified Family Memory Library.")
        return
    key = "frg_same_person_round"
    if st.button("🔄 New comparison", key="new_same_person") or st.session_state.get(key) is None:
        st.session_state[key] = random.choice(pairs)
    same, a, b = st.session_state[key]
    c1, c2 = st.columns(2)
    with c1: st.image(a["photo"], use_container_width=True)
    with c2: st.image(b["photo"], use_container_width=True)
    st.markdown("#### Are these the same person?")
    y, n = st.columns(2)
    answer = None
    if y.button("✅ YES", use_container_width=True, key="same_yes"): answer = True
    if n.button("❌ NO", use_container_width=True, key="same_no"): answer = False
    if answer is not None:
        ok = answer == same
        _family_game_result(pid, "Same Person, Different Time", 100 if ok else 0, 100 if ok else 0, adaptive_difficulty(pid,"Recognition"), 6)
        if ok: celebration("Excellent recognition!")
        else: st.info("Good effort. This is a gentle recognition activity.")
        st.write("The verified answer was:", "Same person" if same else "Different people")
        st.session_state[key] = None


