# ---------- Game 5 ----------
def game_photo_flash(pid):
    """
    Extraordinary 5-Face Sequential Family Recognition Game.

    Flow:
      1. Exactly five verified family photos are shown.
      2. The patient has exactly six seconds to memorize the sequence.
      3. Photos disappear.
      4. Patient writes each person's name and relationship in positions 1-5.
      5. Answers are scored independently, with a sequence bonus.
    """

    PHOTO_FLASH_MEMBERS = 5
    PHOTO_FLASH_SECONDS = 6

    def normalize_answer(value):
        if value is None:
            return ""
        value = str(value).strip().lower()
        for old, new in {
            "-": " ", "_": " ", ".": "", ",": "",
            "'": "", '"': ""
        }.items():
            value = value.replace(old, new)
        return " ".join(value.split())

    def exact_match(answer, verified):
        a = normalize_answer(answer)
        b = normalize_answer(verified)
        return bool(a and b and a == b)

    def reset_round():
        for key in list(st.session_state.keys()):
            if key.startswith("photo_flash_"):
                del st.session_state[key]

    def create_round():
        members = _ready_family(pid)

        if members is None or members.empty:
            return None

        usable = members[
            members["photo_base64"].fillna("").astype(str).str.strip() != ""
        ].copy()

        usable = usable[
            usable["name"].fillna("").astype(str).str.strip() != ""
        ].copy()

        if len(usable) < PHOTO_FLASH_MEMBERS:
            return {
                "error": (
                    "At least five family members must have both a "
                    "verified name and an uploaded photograph."
                )
            }

        chosen = usable.sample(
            n=PHOTO_FLASH_MEMBERS,
            replace=False
        ).reset_index(drop=True)

        people = []
        for position, (_, row) in enumerate(chosen.iterrows(), start=1):
            people.append({
                "position": position,
                "id": int(row["id"]),
                "name": str(row["name"]).strip(),
                "relation": str(row["relation"]).strip(),
                "photo": row["photo_base64"],
            })

        return {
            "people": people,
            "phase": "memorize",
            "started": False,
            "results": None,
            "total_score": 0,
            "name_score": 0,
            "relation_score": 0,
            "sequence_score": 0,
            "perfect": False,
        }

    st.markdown("## 📸 5-Face Family Memory Flash")

    st.markdown(
        """
        <div style="
            padding:22px;
            border-radius:20px;
            border:1px solid rgba(120,120,120,.25);
            margin-bottom:18px;
        ">
            <h2>🧠 Sequential Family Recall Challenge</h2>
            <p style="font-size:17px;">
                Five verified family photographs will appear for
                <b>6 seconds</b>. Memorize their faces and exact order.
                Then write the <b>name</b> and <b>relationship</b> of
                each person in the same sequence.
            </p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    if st.button(
        "🚀 Start New 5-Face Challenge",
        key="photo_flash_start",
        use_container_width=True,
    ):
        reset_round()
        round_data = create_round()
        if round_data is not None:
            st.session_state["photo_flash_round"] = round_data
        st.rerun()

    if "photo_flash_round" not in st.session_state:
        round_data = create_round()
        if round_data is None:
            st.warning("Please upload verified family photographs first.")
            return
        st.session_state["photo_flash_round"] = round_data

    round_data = st.session_state["photo_flash_round"]

    if "error" in round_data:
        st.warning("👨‍👩‍👧‍👦 " + round_data["error"])
        st.info(
            "Add five family members with verified names and uploaded "
            "photos, then return to this game."
        )
        return

    people = round_data["people"]

    # ------------------------------------------------------------
    # PHASE 1: EXACT 6-SECOND PHOTO FLASH
    # ------------------------------------------------------------
    if round_data["phase"] == "memorize":

        st.markdown(
            """
            <div style="
                text-align:center;
                padding:15px;
                border-radius:16px;
                margin-bottom:15px;
            ">
                <h2>👀 Memorize the Sequence</h2>
                <p style="font-size:18px;">
                    Remember who is in positions <b>1 to 5</b>.
                    The photographs will disappear after six seconds.
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )

        st.progress(1.0, text="⏱️ Six-second memory flash")

        cols = st.columns(5)

        for index, person in enumerate(people):
            with cols[index]:
                st.markdown(
                    f"""
                    <div style="
                        text-align:center;
                        font-size:21px;
                        font-weight:800;
                        margin-bottom:8px;
                    ">
                        {person["position"]}
                    </div>
                    """,
                    unsafe_allow_html=True,
                )

                st.image(
                    person["photo"],
                    use_container_width=True
                )

                st.markdown(
                    """
                    <div style="
                        text-align:center;
                        margin-top:6px;
                        font-size:14px;
                    ">
                        Memorize this face
                    </div>
                    """,
                    unsafe_allow_html=True,
                )

        if not round_data["started"]:
            round_data["started"] = True

            try:
                speak(
                    "Look carefully at the five family members. "
                    "Remember their faces and their order from one to five. "
                    "You have six seconds."
                )
            except Exception:
                pass

            # Exactly six seconds of exposure.
            time.sleep(PHOTO_FLASH_SECONDS)

            round_data["phase"] = "recall"
            st.rerun()

        return

    # ------------------------------------------------------------
    # PHASE 2: WRITTEN NAME + RELATIONSHIP RECALL
    # ------------------------------------------------------------
    if round_data["phase"] == "recall":

        st.markdown(
            """
            <div style="
                padding:20px;
                border-radius:18px;
                border:2px solid rgba(100,100,100,.25);
                text-align:center;
                margin-bottom:20px;
            ">
                <h2>🧠 Now Recall Your Family</h2>
                <p style="font-size:17px;">
                    The photographs are hidden. Write the
                    <b>name</b> and <b>relationship</b> for every
                    position in the same order.
                </p>
            </div>
            """,
            unsafe_allow_html=True,
        )

        with st.form("photo_flash_recall_form"):

            for position in range(1, PHOTO_FLASH_MEMBERS + 1):

                st.markdown(
                    f"### 🔢 Position {position}"
                )

                c1, c2 = st.columns(2)

                with c1:
                    st.text_input(
                        "👤 Name",
                        key=f"photo_flash_name_{position}",
                        placeholder="Write the person's name",
                    )

                with c2:
                    st.text_input(
                        "👪 Relationship",
                        key=f"photo_flash_relation_{position}",
                        placeholder="Example: Wife, Son, Brother",
                    )

            submitted = st.form_submit_button(
                "🧠 Check My Memory",
                use_container_width=True,
            )

        if submitted:

            results = []
            name_score = 0
            relation_score = 0
            correct_positions = 0

            for position, person in enumerate(people, start=1):

                patient_name = st.session_state.get(
                    f"photo_flash_name_{position}", ""
                )

                patient_relation = st.session_state.get(
                    f"photo_flash_relation_{position}", ""
                )

                name_correct = exact_match(
                    patient_name,
                    person["name"]
                )

                relation_correct = exact_match(
                    patient_relation,
                    person["relation"]
                )

                if name_correct:
                    name_score += 10

                if relation_correct:
                    relation_score += 10

                if name_correct and relation_correct:
                    correct_positions += 1

                results.append({
                    "position": position,
                    "person": person,
                    "name_correct": name_correct,
                    "relation_correct": relation_correct,
                    "patient_name": patient_name,
                    "patient_relation": patient_relation,
                })

            if correct_positions == 5:
                sequence_score = 50
                perfect = True
            elif correct_positions == 4:
                sequence_score = 25
                perfect = False
            elif correct_positions >= 2:
                sequence_score = 10
                perfect = False
            else:
                sequence_score = 0
                perfect = False

            round_data["results"] = results
            round_data["name_score"] = name_score
            round_data["relation_score"] = relation_score
            round_data["sequence_score"] = sequence_score
            round_data["total_score"] = (
                name_score + relation_score + sequence_score
            )
            round_data["perfect"] = perfect
            round_data["phase"] = "results"

            # Preserve the application's existing recall/journey logging.
            for result in results:
                member = result["person"]
                try:
                    log_family_recall(
                        pid,
                        {
                            "id": member["id"],
                            "relation": member["relation"],
                            "name": member["name"],
                            "photo": member["photo"],
                        },
                        result["name_correct"]
                        and result["relation_correct"],
                    )
                except Exception:
                    pass

            try:
                if correct_positions > 0:
                    add_family_points(
                        pid,
                        correct_positions * FAMILY_POINTS_PER_CORRECT
                    )
            except Exception:
                pass

            st.rerun()

        return

    # ------------------------------------------------------------
    # PHASE 3: RESULTS
    # ------------------------------------------------------------
    if round_data["phase"] == "results":

        results = round_data["results"]

        total_score = round_data["total_score"]
        name_score = round_data["name_score"]
        relation_score = round_data["relation_score"]
        sequence_score = round_data["sequence_score"]

        if round_data["perfect"]:

            try:
                celebration(
                    "🌟 Extraordinary! You remembered all five family "
                    "members in the correct sequence!"
                )
            except Exception:
                pass

            st.success("🏆 PERFECT FAMILY MEMORY!")

            st.markdown(
                """
                <div style="
                    text-align:center;
                    padding:22px;
                    border-radius:20px;
                    margin:15px 0;
                    border:2px solid rgba(100,100,100,.3);
                ">
                    <h1>🌟 5 / 5 PERFECT 🌟</h1>
                    <p style="font-size:19px;">
                        Complete family sequence successfully recalled!
                    </p>
                </div>
                """,
                unsafe_allow_html=True,
            )

        else:
            st.info(
                "👏 Wonderful effort! Let's review what you remembered."
            )

        st.markdown("## 🏅 Memory Performance")

        c1, c2, c3, c4 = st.columns(4)

        with c1:
            st.metric("Total Score", f"{total_score}/150")

        with c2:
            st.metric("Names", f"{name_score}/50")

        with c3:
            st.metric("Relationships", f"{relation_score}/50")

        with c4:
            st.metric("Sequence Bonus", f"{sequence_score}/50")

        st.progress(
            min(total_score / 150, 1.0),
            text=f"Memory achievement: {total_score}/150"
        )

        st.markdown("## 🔎 Your 5-Position Recall")

        for result in results:

            position = result["position"]
            person = result["person"]

            name_ok = result["name_correct"]
            relation_ok = result["relation_correct"]

            if name_ok and relation_ok:
                icon = "🟢"
                status = "Excellent"
            elif name_ok or relation_ok:
                icon = "🟡"
                status = "Good effort"
            else:
                icon = "🔵"
                status = "Let's practice this one"

            st.markdown(
                f"""
                <div style="
                    padding:15px;
                    margin:10px 0;
                    border-radius:15px;
                    border:1px solid rgba(100,100,100,.25);
                ">
                    <h3>{icon} Position {position} — {status}</h3>
                </div>
                """,
                unsafe_allow_html=True,
            )

            c1, c2 = st.columns([1, 2])

            with c1:
                st.image(
                    person["photo"],
                    use_container_width=True
                )

            with c2:

                patient_name = (
                    result["patient_name"].strip()
                    if result["patient_name"]
                    else "No answer"
                )

                patient_relation = (
                    result["patient_relation"].strip()
                    if result["patient_relation"]
                    else "No answer"
                )

                name_icon = "✅" if name_ok else "💡"
                relation_icon = "✅" if relation_ok else "💡"

                st.markdown(
                    f"""
                    **{name_icon} Name**

                    Your answer: **{patient_name}**

                    Verified name: **{person["name"]}**

                    **{relation_icon} Relationship**

                    Your answer: **{patient_relation}**

                    Verified relationship: **{person["relation"]}**
                    """
                )

        correct_count = sum(
            1 for r in results
            if r["name_correct"] and r["relation_correct"]
        )

        if correct_count == 5:
            coach_message = (
                "Outstanding! You remembered all five family members, "
                "their relationships and their sequence."
            )
        elif correct_count >= 3:
            coach_message = (
                "Very good! You remembered several family members. "
                "Repeating the activity can strengthen sequence recall."
            )
        elif correct_count >= 1:
            coach_message = (
                "Good effort. You recognized some family members. "
                "Let's gently practice the sequence again."
            )
        else:
            coach_message = (
                "Thank you for trying. Memory exercises are about practice, "
                "not perfection. We can try another round."
            )

        st.markdown(
            f"""
            <div style="
                padding:18px;
                border-radius:18px;
                margin-top:20px;
                border:1px solid rgba(100,100,100,.25);
            ">
                <h3>🧑‍⚕️ AI Memory Coach</h3>
                <p style="font-size:17px;">{coach_message}</p>
            </div>
            """,
            unsafe_allow_html=True,
        )

        st.markdown("---")

        if st.button(
            "🔄 Play Another 5-Face Challenge",
            key="photo_flash_again",
            use_container_width=True,
        ):

            reset_round()

            new_round = create_round()

            if new_round is not None:
                st.session_state["photo_flash_round"] = new_round

            st.rerun()

        return


def game_beside_whom(pid):
    st.markdown("### 6️⃣ Who Was Standing Beside Whom?")
    clues=query_df("SELECT * FROM family_relationship_clues WHERE patient_id=? ORDER BY id DESC",(pid,))
    if clues.empty: st.info("Add a verified relationship clue in 🗂️ Verified Family Memory Library."); return
    members=_ready_family(pid)
    labels={int(r["id"]):_member_display(r) for _,r in members.iterrows()}
    key="frg_beside_round"
    if st.button("🔄 New beside-whom question",key="new_beside") or st.session_state.get(key) is None:
        st.session_state[key]=clues.sample(1).iloc[0].to_dict()
    c=st.session_state[key]; anchor=labels.get(int(c["anchor_member_id"]),"Family member"); correct=labels.get(int(c["neighbor_member_id"]),"Family member")
    if int(c.get("group_photo_id") or 0):
        g=query_df("SELECT * FROM family_group_photos WHERE id=?",(int(c["group_photo_id"]),))
        if not g.empty: st.image(g.iloc[0]["photo_base64"],use_container_width=True)
    st.markdown(f"**Who was {c['direction']} {anchor}?**")
    options=[v for k,v in labels.items() if v!=anchor]
    ans=st.radio("Choose a family member",options,key="beside_answer")
    if st.button("✅ Check",key="check_beside"):
        ok=_normalize_answer(ans)==_normalize_answer(correct)
        _family_game_result(pid,"Who Was Standing Beside Whom",100 if ok else 0,100 if ok else 0,adaptive_difficulty(pid,"Recognition"),6)
        if ok: celebration("Perfect! You remembered the family arrangement.")
        else: st.info(f"Verified answer: {correct}.")


