def game_face_sequence(pid):
    st.markdown("### 7️⃣ Family Face Sequence Challenge")
    members=_ready_family(pid)
    if len(members)<3: st.info("Upload at least 3 family photos."); return
    level=adaptive_difficulty(pid,"Recognition"); n=min(6,max(3,2+level))
    key="frg_face_sequence"
    if st.button("🔄 New face sequence",key="new_face_sequence") or st.session_state.get(key) is None:
        seq=members.sample(min(n,len(members)),replace=False).to_dict("records")
        st.session_state[key]={"seq":seq,"phase":"show"}
    r=st.session_state[key]
    if r["phase"]=="show":
        st.write("Memorize the order:")
        cols=st.columns(min(4,len(r["seq"])))
        for i,p in enumerate(r["seq"]):
            with cols[i%len(cols)]: st.image(p["photo_base64"],use_container_width=True); st.caption(f"{i+1}. {_member_display(p)}")
        if st.button("🙈 Hide sequence",key="hide_face_sequence"): r["phase"]="answer"; st.rerun()
        return
    labels=[_member_display(p) for p in members.to_dict("records")]
    picks=[]
    for i in range(len(r["seq"])):
        picks.append(st.selectbox(f"Position {i+1}",labels,key=f"face_seq_pick_{i}"))
    correct=[_normalize_answer(_member_display(p)) for p in r["seq"]]
    got=[_normalize_answer(x) for x in picks]
    accuracy=sum(a==b for a,b in zip(correct,got))/len(correct)*100
    if st.button("✅ Check sequence",key="check_face_sequence"):
        _family_game_result(pid,"Family Face Sequence Challenge",accuracy,accuracy,level,8)
        if accuracy==100: celebration("Fantastic sequence memory!")
        else: st.info(f"Good effort — {int(accuracy)}% of the sequence was recalled correctly.")


