def game_photo_puzzle(pid):
    st.markdown("### 9️⃣ Family Photo Puzzle Memory")
    if not PIL_OK: st.error("Pillow is required for the photo-puzzle activity. Install it with: pip install pillow"); return
    members=_ready_family(pid)
    if members.empty: st.info("Upload family photos first."); return
    level=adaptive_difficulty(pid,"Recognition"); pieces_n=4 if level<4 else 6
    key="frg_photo_puzzle"
    if st.button("🔄 New photo puzzle",key="new_photo_puzzle") or st.session_state.get(key) is None:
        target=members.sample(1).iloc[0]; st.session_state[key]={"target":target.to_dict(),"order":random.sample(range(pieces_n),pieces_n),"pieces_n":pieces_n}
    r=st.session_state[key]; raw=_data_url_bytes(r["target"]["photo_base64"])
    if not raw: st.error("Photo could not be read."); return
    im=Image.open(BytesIO(raw)).convert("RGB"); w,h=im.size
    pw,ph=w//2,h//(pieces_n//2)
    pieces=[]
    rows=pieces_n//2
    for rr in range(rows):
        for cc in range(2): pieces.append(im.crop((cc*pw,rr*ph,min((cc+1)*pw,w),min((rr+1)*ph,h))))
    st.write(f"Rebuild this family photo mentally from {pieces_n} scrambled pieces.")
    cols=st.columns(2)
    for i,idx in enumerate(r["order"]):
        with cols[i%2]: st.image(pieces[idx],use_container_width=True); st.caption(f"Piece {i+1}")
    labels=[str(i+1) for i in range(pieces_n)]
    answers=[st.selectbox(f"Which original piece belongs at position {i+1}?",labels,key=f"puzzle_{i}") for i in range(pieces_n)]
    expected=[str(i+1) for i in range(pieces_n)]
    if st.button("🧩 Check puzzle order",key="check_photo_puzzle"):
        accuracy=sum(a==b for a,b in zip(answers,expected))/pieces_n*100
        _family_game_result(pid,"Family Photo Puzzle Memory",accuracy,accuracy,level,10)
        st.markdown(f"**Photo shown:** {_member_display(r['target'])}")
        if accuracy==100: celebration("Excellent photo puzzle memory!")
        else: st.info(f"Good effort — {int(accuracy)}% correct. The activity is for engagement, not diagnosis.")


