def game_family_memory_journey(pid):
    st.markdown("### 1️⃣3️⃣ AI Family Memory Journey")
    members=_ready_family(pid)
    journey=get_journey_data(pid)
    stories=query_df("SELECT * FROM family_stories WHERE patient_id=? ORDER BY id DESC",(pid,))
    events=query_df("SELECT * FROM family_events WHERE patient_id=? ORDER BY event_date DESC",(pid,))
    pool=[]
    for _,r in members.iterrows(): pool.append({"photo":r["photo_base64"],"title":_member_display(r),"detail":r["relation"]})
    for _,r in stories.iterrows():
        if r["photo_base64"]: pool.append({"photo":r["photo_base64"],"title":"Family story","detail":r["caption"] or "Voice memory"})
    for _,r in events.iterrows():
        if r["photo_base64"]: pool.append({"photo":r["photo_base64"],"title":r["event_name"],"detail":str(r["event_date"])})
    if not pool: st.info("Add family photos or verified memories to begin the journey."); return
    key="frg_memory_journey_index"
    if key not in st.session_state: st.session_state[key]=0
    item=pool[st.session_state[key]%len(pool)]
    st.markdown(f"<div class='hero'><div class='pill'>Personalized • Verified only</div><h2>{item['title']}</h2><p>{item['detail']}</p></div>",unsafe_allow_html=True)
    st.image(item["photo"],use_container_width=True)
    c1,c2,c3=st.columns(3)
    with c1:
        if st.button("⬅️ Previous memory",key="journey_prev"): st.session_state[key]=(st.session_state[key]-1)%len(pool); st.rerun()
    with c2:
        if st.button("🔊 Read memory aloud",key="journey_speak"): speak(f"{item['title']}. {item['detail']}")
    with c3:
        if st.button("Next memory ➡️",key="journey_next"): st.session_state[key]=(st.session_state[key]+1)%len(pool); st.rerun()
    st.markdown("#### 🌟 Your recall journey")
    if journey:
        total_stars=sum(int(x["stars"]) for x in journey); st.metric("Family recall stars",total_stars); st.write(f"You have completed {len(journey)} family-recall day(s).")
    else:
        st.info("Play the family recognition games to begin building your recall journey.")
    st.caption("The journey prioritizes familiar uploaded people and caregiver-verified stories/events; it does not create memories or facts.")


