# ================================================================
# GPS-SYSYEM — REAL-TIME SAFE NAVIGATION GUIDE
# Uses browser GPS + OpenStreetMap/Nominatim + OSRM routing.
# The browser watches the patient's live position and speaks the next
# route instruction. Location permission and HTTPS are required.
# ================================================================

def _gps_geocode(destination):
    try:
        response = requests.get(
            "https://nominatim.openstreetmap.org/search",
            params={"q": destination, "format": "json", "limit": 1},
            headers={"User-Agent": "MindBlossom-NER-Care-GPS/1.0"},
            timeout=12,
        )
        response.raise_for_status()
        data = response.json()
        if not data:
            return None
        return float(data[0]["lat"]), float(data[0]["lon"]), data[0].get("display_name", destination)
    except Exception as exc:
        st.error(f"Could not find that destination: {exc}")
        return None


def _gps_route(start_lat, start_lon, end_lat, end_lon):
    try:
        url = (
            "https://router.project-osrm.org/route/v1/driving/"
            f"{start_lon},{start_lat};{end_lon},{end_lat}"
        )
        response = requests.get(
            url,
            params={"overview": "full", "geometries": "geojson", "steps": "true"},
            timeout=20,
            headers={"User-Agent": "MindBlossom-NER-Care-GPS/1.0"},
        )
        response.raise_for_status()
        data = response.json()
        if data.get("code") != "Ok" or not data.get("routes"):
            return None
        return data["routes"][0]
    except Exception as exc:
        st.error(f"Could not calculate a route: {exc}")
        return None


def _gps_instruction(step):
    maneuver = step.get("maneuver", {})
    typ = maneuver.get("type", "")
    mod = maneuver.get("modifier", "")
    name = (step.get("name") or "").strip()
    road = f" onto {name}" if name else ""
    if typ == "depart":
        return f"Start by heading {mod or 'forward'}{road}."
    if typ == "arrive":
        return "You have arrived at your destination."
    if typ == "roundabout" or typ == "rotary":
        exit_no = maneuver.get("exit")
        return f"Enter the roundabout and take exit {exit_no}{road}." if exit_no else f"Enter the roundabout{road}."
    if typ == "turn":
        direction = mod.replace("sharp", "sharp ").replace("slight", "slight ") if mod else ""
        return f"Turn {direction} {road}.".replace("  ", " ")
    if typ == "continue":
        return f"Continue {mod or 'straight'}{road}."
    if typ == "fork":
        return f"Keep {mod or 'straight'}{road}."
    if typ == "merge":
        return f"Merge {mod or 'ahead'}{road}."
    return f"Continue toward your destination{road}."


def _gps_live_map_html(dest_lat, dest_lon, destination_name):
    dest_name = html.escape(str(destination_name)).replace("'", "\\'")
    map_id = f"mindblossom_live_gps_{int(time.time() * 1000)}"
    return f"""
    <div style="font-family:Arial,sans-serif;border-radius:18px;overflow:hidden;border:1px solid #ddd;">
      <div style="padding:12px 16px;background:#f4f8ff;font-size:18px;font-weight:700;">
        🧭 Live AI Guide • {dest_name}
      </div>
      <div id="{map_id}" style="height:560px;width:100%;"></div>
      <div id="{map_id}_status" style="padding:12px 16px;background:#fff;font-size:16px;">
        📍 Requesting live GPS location…
      </div>
    </div>
    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script>
    (() => {{
      const DEST = [{dest_lat}, {dest_lon}];
      const map = L.map('{map_id}').setView(DEST, 15);
      L.tileLayer('https://{{s}}.tile.openstreetmap.org/{{z}}/{{x}}/{{y}}.png', {{
        maxZoom: 19, attribution: '&copy; OpenStreetMap contributors'
      }}).addTo(map);
      const destination = L.marker(DEST).addTo(map).bindPopup('Destination: {dest_name}').openPopup();
      let patientMarker = null;
      let routeLine = null;
      let watchId = null;
      let steps = [];
      let nextStep = 0;
      let lastSpoken = '';
      let lastSpeakTime = 0;
      let lastRouteAt = 0;
      const status = document.getElementById('{map_id}_status');

      function speakGuide(text) {{
        if (!('speechSynthesis' in window)) return;
        const now = Date.now();
        if (text === lastSpoken && now - lastSpeakTime < 10000) return;
        lastSpoken = text; lastSpeakTime = now;
        speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(text);
        u.rate = 0.82; u.pitch = 1.0; u.volume = 1.0;
        speechSynthesis.speak(u);
      }}

      function distanceMeters(aLat, aLon, bLat, bLon) {{
        const R=6371000, rad=Math.PI/180;
        const dLat=(bLat-aLat)*rad, dLon=(bLon-aLon)*rad;
        const a=Math.sin(dLat/2)**2 + Math.cos(aLat*rad)*Math.cos(bLat*rad)*Math.sin(dLon/2)**2;
        return 2*R*Math.asin(Math.sqrt(a));
      }}

      function instruction(step) {{
        const m=step.maneuver||{{}}, type=m.type||'', mod=m.modifier||'';
        const name=(step.name||'').trim();
        const road=name ? ' onto '+name : '';
        if(type==='depart') return 'Start by heading '+(mod||'forward')+road+'.';
        if(type==='arrive') return 'You have arrived at your destination.';
        if(type==='roundabout'||type==='rotary') return m.exit ? 'Enter the roundabout and take exit '+m.exit+road+'.' : 'Enter the roundabout'+road+'.';
        if(type==='turn') return 'Turn '+(mod||'ahead')+road+'.';
        if(type==='continue') return 'Continue '+(mod||'straight')+road+'.';
        if(type==='fork') return 'Keep '+(mod||'straight')+road+'.';
        if(type==='merge') return 'Merge '+(mod||'ahead')+road+'.';
        return 'Continue toward your destination'+road+'.';
      }}

      async function buildRoute(lat, lon, force=false) {{
        if(!force && Date.now()-lastRouteAt < 7000) return;
        lastRouteAt=Date.now();
        status.innerHTML='🛰️ GPS locked. Calculating the safest available road route…';
        const url='https://router.project-osrm.org/route/v1/driving/'+lon+','+lat+';'+DEST[1]+','+DEST[0]+'?overview=full&geometries=geojson&steps=true';
        try {{
          const response=await fetch(url);
          const data=await response.json();
          if(data.code!=='Ok'||!data.routes||!data.routes.length) throw new Error('No route was returned');
          const route=data.routes[0];
          const points=route.geometry.coordinates.map(x=>[x[1],x[0]]);
          if(routeLine) map.removeLayer(routeLine);
          routeLine=L.polyline(points,{{weight:7}}).addTo(map);
          steps=(route.legs[0].steps||[]).filter(x=>x.maneuver&&x.maneuver.location).map(x=>({{
            lat:x.maneuver.location[1],lon:x.maneuver.location[0],text:instruction(x),distance:x.distance
          }}));
          nextStep=0;
          const km=(route.distance/1000).toFixed(1);
          const mins=Math.round(route.duration/60);
          map.fitBounds(routeLine.getBounds(),{{padding:[25,25]}});
          status.innerHTML='🧭 <b>AI Guide ready.</b> '+km+' km • about '+mins+' min. Tap the map to start voice guidance.';
          speakGuide('Your route is ready. Tap the map to start voice guidance.');
        }} catch(e) {{
          status.innerHTML='⚠️ Route service unavailable right now. Keep the patient with a caregiver and try again.';
        }}
      }}

      function updatePosition(position) {{
        const lat=position.coords.latitude, lon=position.coords.longitude;
        if(!patientMarker) patientMarker=L.marker([lat,lon]).addTo(map).bindPopup('Patient location');
        else patientMarker.setLatLng([lat,lon]);
        map.setView([lat,lon],Math.max(map.getZoom(),16));
        if(!steps.length) {{ buildRoute(lat,lon,true); return; }}
        while(nextStep<steps.length) {{
          const target=steps[nextStep];
          const d=distanceMeters(lat,lon,target.lat,target.lon);
          if(d<45) {{ speakGuide(target.text); nextStep++; continue; }}
          const remaining=distanceMeters(lat,lon,DEST[0],DEST[1]);
          status.innerHTML='🧭 <b>Next:</b> '+target.text+'<br>📏 '+Math.round(d)+' m to next instruction • '+Math.round(remaining)+' m to destination';
          if(d<100) speakGuide(target.text);
          break;
        }}
        if(nextStep>=steps.length) {{
          status.innerHTML='🎉 <b>You have arrived.</b> Stay with your caregiver and follow the destination instructions.';
          speakGuide('You have arrived at your destination.');
        }}
      }}

      function gpsError(err) {{
        status.innerHTML='⚠️ GPS permission is needed for live navigation. Please allow Location access, enable GPS, and keep this page open.';
      }}

      map.on('click',()=>{{
        if(steps.length) speakGuide('Navigation started. '+steps[Math.min(nextStep,steps.length-1)].text);
      }});
      if(navigator.geolocation) {{
        watchId=navigator.geolocation.watchPosition(updatePosition,gpsError,{{enableHighAccuracy:true,maximumAge:2000,timeout:15000}});
      }} else {{ gpsError({{message:'GPS is not supported'}}); }}
    }})();
    </script>
    """


def gps_system_page():
    st.markdown("## 📍 GPS-sysyem")
    st.markdown(
        "### 🧭 Real-time AI navigation for the patient\n"
        "Set the destination first. The phone then uses live GPS, shows the complete road path, "
        "recalculates the route when needed, and gives spoken turn-by-turn guidance."
    )
    st.warning(
        "Safety: this is a navigation aid, not a replacement for a caregiver. "
        "The patient should not cross roads or walk while looking at the screen. "
        "Keep a caregiver nearby."
    )

    if "gps_destination" not in st.session_state:
        st.session_state.gps_destination = None

    destination = st.text_input(
        "📍 Where do you want to go?",
        value=st.session_state.gps_destination[2] if st.session_state.gps_destination else "",
        placeholder="Example: Gauhati Medical College, Guwahati",
        help="Enter a real address, landmark, hospital, home, shop or station.",
    )

    c1, c2 = st.columns(2)
    with c1:
        if st.button("🗺️ Set destination", use_container_width=True):
            if not destination.strip():
                st.error("Please enter the place where the patient wants to go.")
            else:
                dest = _gps_geocode(destination.strip())
                if dest:
                    st.session_state.gps_destination = dest
                    st.rerun()
    with c2:
        if st.button("🧹 Clear navigation", use_container_width=True):
            st.session_state.gps_destination = None
            st.rerun()

    dest = st.session_state.get("gps_destination")
    if dest:
        st.success(f"Destination set: {dest[2]}")
        st.markdown("#### 🛰️ Live GPS + AI voice guide")
        st.components.v1.html(
            _gps_live_map_html(dest[0], dest[1], dest[2]),
            height=650,
            scrolling=False,
        )
        st.caption(
            "Live map/routing uses OpenStreetMap + OSRM. Your browser must have HTTPS, GPS/location permission, "
            "and an internet connection. The route can change if the patient moves away from it."
        )
    else:
        st.markdown(
            """
            <div class='hero' style='text-align:center;'>
              <div style='font-size:64px;'>🗺️</div>
              <h2>Set a destination to begin</h2>
              <p>The app will then request live GPS, draw the real road path and provide spoken navigation.</p>
            </div>
            """,
            unsafe_allow_html=True,
        )


def journey_page():
    st.markdown("## 🧭 My Journey")

    ai_doctor_intro(
        "my_journey",
        "This is your family-recall journey! Every day you play the "
        "Family Recognition games, a new step lights up here, with "
        "stars for every relative you remembered and their photo "
        "right below.",
    )

    pid = patient["id"]
    days = get_journey_data(pid)

    st.markdown(JOURNEY_CSS, unsafe_allow_html=True)

    if not days:
        st.markdown(
            """
            <div class="journey-card">
              <div class="journey-header">
                <div class="journey-title">My Journey</div>
                <div class="journey-sub">Family recall progress, one day at a time</div>
              </div>
              <div class="journey-empty">
                🔒 No steps yet. Play a round in
                <b>🧑‍🤝‍🧑 Family Recognition</b> (Doctor's Group Challenge or
                the Memory Flash Game) to light up Day 1!
              </div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        return

    LOCKED_PREVIEW = 2  # a couple of "not unlocked yet" days shown ahead
    PER_ROW = 4
    SPACING_X, SPACING_Y = 230, 150
    TOP_PAD, LEFT_PAD = 110, 90

    total_nodes = len(days) + LOCKED_PREVIEW
    nodes = []
    for i in range(total_nodes):
        row = i // PER_ROW
        col = i % PER_ROW
        display_col = col if (row % 2 == 0) else (PER_ROW - 1 - col)
        nodes.append(
            {
                "x": LEFT_PAD + display_col * SPACING_X,
                "y": TOP_PAD + row * SPACING_Y,
            }
        )

    width = LEFT_PAD + PER_ROW * SPACING_X
    rows = (total_nodes - 1) // PER_ROW + 1
    height = TOP_PAD + rows * SPACING_Y

    # ---- connecting path, one gradient/dashed segment per hop ----
    path_parts = []
    for i in range(1, total_nodes):
        x0, y0 = nodes[i - 1]["x"], nodes[i - 1]["y"]
        x1, y1 = nodes[i]["x"], nodes[i]["y"]
        locked_segment = i >= len(days)
        color_from = JOURNEY_PALETTE[(i - 1) % len(JOURNEY_PALETTE)]
        color_to = JOURNEY_PALETTE[i % len(JOURNEY_PALETTE)]
        gid = f"journeyGrad{i}"
        # A flowing, unmistakably curved route rather than a straight connector.
        mid_x = (x0 + x1) / 2
        bend = 54 if (i % 2) else -54
        c1x, c1y = mid_x, y0 + bend
        c2x, c2y = mid_x, y1 - bend
        if locked_segment:
            stroke = "#4b5563"
            dash = 'stroke-dasharray="10,12"'
        else:
            stroke = f"url(#{gid})"
            dash = ""
        path_parts.append(
            f'<defs><linearGradient id="{gid}" x1="{x0}" y1="{y0}" x2="{x1}" y2="{y1}" '
            f'gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="{color_from}"/>'
            f'<stop offset="1" stop-color="{color_to}"/></linearGradient></defs>'
            f'<path d="M {x0} {y0} C {c1x} {c1y}, {c2x} {c2y}, {x1} {y1}" '
            f'fill="none" stroke="{stroke}" stroke-width="7" '
            f'stroke-linecap="round" {dash}/>'
        )

    svg = (
        f'<svg width="{width}" height="{height}" '
        f'style="position:absolute;top:0;left:0;">' + "".join(path_parts) + "</svg>"
    )

    # ---- node circles + day / star bubbles ----
    node_html = []
    for i, node in enumerate(nodes):
        x, y = node["x"], node["y"]
        bubble_left = x - 60
        bubble_top = y - 86
        if i >= len(days):
            node_html.append(
                f'<div class="journey-node journey-node-locked" '
                f'style="left:{x-32}px; top:{y-32}px;">🔒</div>'
                f'<div class="journey-bubble journey-bubble-locked" '
                f'style="left:{bubble_left}px; top:{bubble_top}px;">'
                f'Day {i + 1}</div>'
            )
        else:
            day = days[i]
            color = JOURNEY_PALETTE[i % len(JOURNEY_PALETTE)]
            stars = "⭐" * day["stars"] if day["stars"] else "—"
            node_html.append(
                f'<div class="journey-node" style="left:{x-32}px; top:{y-32}px; '
                f'background:{color};">{day["day_number"]}</div>'
                f'<div class="journey-bubble" style="left:{bubble_left}px; '
                f'top:{bubble_top}px; border-left:4px solid {color};">'
                f'<div class="journey-bubble-title">Day {day["day_number"]}</div>'
                f'<div class="journey-bubble-stars">{stars}</div></div>'
            )

    st.markdown(
        f"""
        <div class="journey-card">
          <div class="journey-header">
            <div class="journey-title">My Journey</div>
            <div class="journey-sub">Family recall progress, one day at a time</div>
          </div>
          <div class="journey-canvas" style="width:{width}px; height:{height}px;">
            {svg}
            {''.join(node_html)}
          </div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    # ---- advanced bit: the actual recalled photos, day by day ----
    st.markdown("### 📸 Who they recalled, day by day")
    st.caption(
        "Only relatives correctly recognized that day appear here — a "
        "gentle, positive record of progress rather than mistakes."
    )

    for day in reversed(days):
        stars_label = f"{'⭐' * day['stars']}" if day["stars"] else "No stars yet"
        with st.expander(
            f"Day {day['day_number']} — {day['date']} · {stars_label}",
            expanded=(day["day_number"] == days[-1]["day_number"]),
        ):
            if not day["members"]:
                st.write(
                    "No family photos were correctly recalled this day "
                    "(a photo may not have been uploaded for the relative "
                    "recognized, or none were recognized yet)."
                )
                continue
            cols = st.columns(min(4, len(day["members"])))
            for j, member in enumerate(day["members"]):
                with cols[j % len(cols)]:
                    st.image(member["photo"], use_container_width=True)
                    who = member["relation"] + (
                        f", {member['name']}" if member["name"] else ""
                    )
                    st.markdown(
                        f'<div style="text-align:center;font-weight:700;">{who}</div>',
                        unsafe_allow_html=True,
                    )


