    b=st.selectbox("Who stood beside them?",[x for x in df.id.tolist() if x!=a],format_func=lambda x:next((r['name'] or r['relation'] for _,r in df.iterrows() if r['id']==x),str(x)),key='ms6_b')
    st.info("Use caregiver-entered group-photo relationship clues for a fully verified spatial answer. This screen never invents a relationship.")
    if st.button("Save answer",key='ms6_check'):
        execute("INSERT INTO family_relationship_clues (patient_id,anchor_member_id,neighbor_member_id,direction,created_at) VALUES (?,?,?,?,?)",(pid,int(a),int(b),'beside',now_text()))
