def _ms_sequence(pid):
    df=_ms_image_options(_ms_member_rows(pid))
    st.markdown("### 🔢 Family Face Sequence Challenge")
    st.caption("How to run: press Start, remember the order, then rebuild it with the selectors.")
    if len(df)<3: st.warning("Add at least 3 family photos first."); return
    if st.button("▶️ Start sequence",key='ms7_start'):
        st.session_state.ms7=df.sample(min(5,len(df))).to_dict('records')
        st.session_state.ms7_show=True
    seq=st.session_state.get('ms7')
    if seq:
        if st.session_state.get('ms7_show'):
            _ms_photo_grid(pd.DataFrame(seq),labels=[f"Position {i+1}" for i in range(len(seq))])
            if st.button("Hide and rebuild",key='ms7_hide'): st.session_state.ms7_show=False; st.rerun()
        else:
            ids=df.id.tolist(); answers=[]
            for i in range(len(seq)):
                answers.append(st.selectbox(f"Position {i+1}",ids,index=0,format_func=lambda x:next((r['name'] or r['relation'] for _,r in df.iterrows() if r['id']==x),str(x)),key=f'ms7_{i}'))
            if st.button("Check sequence",key='ms7_check'):
                ok=answers==[r['id'] for r in seq]; _ms_record(pid,'Family Face Sequence Challenge',100 if ok else 0,1 if ok else 0,xp=10 if ok else 2); _ms_feedback(ok,'Perfect sequence!' if ok else 'Good attempt. Let’s try the sequence again.')


def _ms_relation_target(pid):
    df=_ms_image_options(_ms_member_rows(pid))
    st.markdown("### 👶 Find My Grandchild / Child / Sibling")
    st.caption("How to run: choose a verified relationship category, then identify the matching face.")
    if df.empty: st.warning("Add family members with photos first."); return
    rels=sorted(df.relation.dropna().unique().tolist()); rel=st.selectbox("Relationship to find",rels,key='ms8_rel')
    candidates=df[df.relation==rel]
    if candidates.empty: st.info("No verified member in this relationship category."); return
    if st.button("Start",key='ms8_start'):
        target=candidates.sample(1).iloc[0].to_dict(); choices=df.sample(min(4,len(df))).to_dict('records');
        if target['id'] not in [x['id'] for x in choices]: choices[-1]=target
        random.shuffle(choices); st.session_state.ms8=(target,choices)
    state=st.session_state.get('ms8')
    if state:
        target,choices=state; _ms_photo_grid(pd.DataFrame(choices))
        pick=st.selectbox("Choose the requested person",[x['id'] for x in choices],format_func=lambda x:next((r['name'] or r['relation'] for r in choices if r['id']==x),str(x)),key='ms8_pick')
        if st.button('Check',key='ms8_check'):
            ok=pick==target['id']; _ms_record(pid,'Find My Grandchild / Child / Sibling',100 if ok else 0,1 if ok else 0,xp=10 if ok else 2); _ms_feedback(ok,'You found them!' if ok else 'That is okay. Let’s look once more.')


