def _ms_journey(pid):
    st.markdown("### 🌌 AI Family Memory Journey")
    st.caption("How to run: add verified family photos/stories/events, then use Previous/Next and Read Aloud. No facts are invented.")
    members=_ms_image_options(_ms_member_rows(pid))
    stories=query_df('SELECT * FROM family_stories WHERE patient_id=? ORDER BY id DESC',(pid,))
    events=query_df('SELECT * FROM family_events WHERE patient_id=? ORDER BY event_date DESC',(pid,))
    pool=[]
    for _,r in members.iterrows(): pool.append({'photo':r.photo_base64,'title':r.name or r.relation,'detail':r.relation})
    for _,r in stories.iterrows():
        if r.photo_base64: pool.append({'photo':r.photo_base64,'title':'Family story','detail':r.caption})
    for _,r in events.iterrows():
        if r.photo_base64: pool.append({'photo':r.photo_base64,'title':r.event_name,'detail':str(r.event_date)})
    if not pool: st.info('Add verified memories to begin.'); return
    key='ms13_index'; st.session_state.setdefault(key,0); item=pool[st.session_state[key]%len(pool)]
    st.image(item['photo'],use_container_width=True); st.markdown(f"**{item['title']}**  \n{item['detail']}")
    c1,c2,c3=st.columns(3)
    with c1:
        if st.button('⬅️ Previous',key='ms13_prev'): st.session_state[key]=(st.session_state[key]-1)%len(pool); st.rerun()
    with c2:
        if st.button('🔊 Read aloud',key='ms13_speak'): speak(f"{item['title']}. {item['detail']}")
    with c3:
        if st.button('Next ➡️',key='ms13_next'): st.session_state[key]=(st.session_state[key]+1)%len(pool); st.rerun()


