def _adv_bucket(t):
    """Map a time (HH:MM) to a broad time-of-day bucket."""
    try:
        h = int(str(t).split(':')[0])
    except Exception:
        h = 12
    if 6 <= h < 12: return 'Morning'
    if 12 <= h < 17: return 'Afternoon'
    if 17 <= h < 21: return 'Evening'
    return 'Night'


def _adv_1_sundowning(pid):
    st.markdown("### 🌇 Sundowning Pattern Tracker")
    st.caption("Log moments of confusion, agitation or restlessness with the time they happened, so caregivers can spot the time of day symptoms tend to peak (a common pattern called 'sundowning') and plan calmer routines around it.")
    c1, c2 = st.columns(2)
    with c1:
        log_date = st.date_input('Date', value=date.today(), key='adv1_date')
        log_time = st.time_input('Time observed', key='adv1_time')
    with c2:
        symptom = st.selectbox('What was observed', ['Agitation', 'Confusion', 'Anxiety', 'Restlessness', 'Repetitive questioning', 'Aggression', 'Withdrawal', 'Other'], key='adv1_symptom')
        severity = st.slider('Severity', 1, 5, 2, key='adv1_severity')
    notes = st.text_input('Optional notes', key='adv1_notes')
    if st.button('Save observation', key='adv1_save'):
        t_str = log_time.strftime('%H:%M')
        execute('INSERT INTO adv_sundowning (patient_id, log_date, log_time, bucket, symptom, severity, notes, created_at) VALUES (?,?,?,?,?,?,?,?)',
                (pid, str(log_date), t_str, _adv_bucket(t_str), symptom, severity, notes.strip(), now_text()))
        st.success('Observation logged.')

    rows = query_df('SELECT * FROM adv_sundowning WHERE patient_id=? ORDER BY log_date DESC, log_time DESC', (pid,))
    if rows.empty:
        st.info('No observations logged yet.')
        return
    st.markdown("#### Average severity by time of day")
    order = ['Morning', 'Afternoon', 'Evening', 'Night']
    avg = rows.groupby('bucket')['severity'].mean().reindex(order).fillna(0)
    fig = px.bar(x=order, y=avg.values, labels={'x': 'Time of day', 'y': 'Average severity'}, color=avg.values, color_continuous_scale='OrRd')
    st.plotly_chart(fig, use_container_width=True)
    peak = avg.idxmax() if avg.max() > 0 else None
    if peak:
        st.warning(f"📌 Symptoms have tended to be strongest in the **{peak}**. Consider planning calming activities, dimmer lighting, or a caregiver check-in around that time.")
    st.dataframe(rows[['log_date', 'log_time', 'symptom', 'severity', 'notes']], use_container_width=True, hide_index=True)


def _adv_2_wandering(pid):
    st.markdown("### 🧭 Wandering Safety Check-In Log")
    st.caption("Define safe zones (e.g. 'Living room', 'Garden') and log check-ins so caregivers can quickly see how long it has been since the last confirmed check-in. This is a manual safety log, not GPS tracking.")
    with st.expander('➕ Add a safe zone'):
        zn = st.text_input('Zone name', key='adv2_zone_name')
        zd = st.text_input('Description (optional)', key='adv2_zone_desc')
        if st.button('Save zone', key='adv2_zone_save') and zn.strip():
            execute('INSERT INTO adv_safezones (patient_id, zone_name, description, created_at) VALUES (?,?,?,?)', (pid, zn.strip(), zd.strip(), now_text()))
            st.success('Safe zone saved.')

    zones = query_df('SELECT * FROM adv_safezones WHERE patient_id=? ORDER BY id', (pid,))
    if zones.empty:
        st.info('Add at least one safe zone above to start logging check-ins.')
        return

    zone_names = zones['zone_name'].tolist()
    c1, c2 = st.columns([2, 1])
    with c1:
        chosen = st.selectbox('Check in at zone', zone_names, key='adv2_checkin_zone')
        note = st.text_input('Optional note', key='adv2_checkin_note')
    with c2:
        st.write('')
        st.write('')
        if st.button('✅ Log check-in now', key='adv2_checkin_btn'):
            execute('INSERT INTO adv_checkins (patient_id, zone_name, notes, created_at) VALUES (?,?,?,?)', (pid, chosen, note.strip(), now_text()))
            st.success(f'Check-in logged for {chosen}.')

    checkins = query_df('SELECT * FROM adv_checkins WHERE patient_id=? ORDER BY created_at DESC', (pid,))
    st.markdown("#### Time since last check-in")
    if checkins.empty:
        st.warning('No check-ins logged yet.')
    else:
        last = checkins.iloc[0]
        last_dt = datetime.strptime(last['created_at'], '%Y-%m-%d %H:%M:%S') if 'created_at' in last and last['created_at'] else None
        if last_dt:
            hours = (datetime.now() - last_dt).total_seconds() / 3600
            if hours > 6:
                st.error(f"⚠️ Last check-in was at **{last['zone_name']}**, {hours:.1f} hours ago. Consider checking in on them.")
            else:
                st.success(f"Last check-in: **{last['zone_name']}**, {hours:.1f} hours ago.")
        st.dataframe(checkins[['zone_name', 'notes', 'created_at']].head(15), use_container_width=True, hide_index=True)


def _adv_3_caregiver_burden(pid):
    st.markdown("### 🎗️ Caregiver Self-Care Check-In")
    st.caption("A short, private self-reflection for the caregiver — not the patient. It highlights rising strain early so support can be arranged before burnout. This is a wellbeing check-in, not a clinical or diagnostic tool.")
    name = st.text_input('Your name (optional)', key='adv3_name')
    questions = [
        'I feel drained by caregiving tasks most days.',
        'I have little time left for myself or my own needs.',
        'I feel worried or anxious about the person I care for.',
        'I feel I have enough support from family, friends or services.',
        'I feel confident I can keep up this level of care long-term.',
    ]
    reverse = [False, False, False, True, True]
    scores = []
    for i, q in enumerate(questions):
        s = st.slider(q, 0, 4, 2, key=f'adv3_q{i}', help='0 = Not at all, 4 = Very much')
        scores.append(4 - s if reverse[i] else s)
    if st.button('Save check-in', key='adv3_save'):
        total = sum(scores)
        level = 'Low strain' if total <= 6 else ('Moderate strain' if total <= 13 else 'High strain')
        execute('INSERT INTO adv_caregiver_burden (patient_id, caregiver_name, q1,q2,q3,q4,q5, total_score, level, created_at) VALUES (?,?,?,?,?,?,?,?,?,?)',
                (pid, name.strip(), scores[0], scores[1], scores[2], scores[3], scores[4], total, level, now_text()))
        st.success(f'Check-in saved. Current level: **{level}** ({total}/20).')
        if level == 'High strain':
            st.warning('💙 Your score suggests noticeable strain. Please consider reaching out to family, a support group, or a healthcare professional for respite support — you matter too.')

    rows = query_df('SELECT * FROM adv_caregiver_burden WHERE patient_id=? ORDER BY created_at', (pid,))
    if not rows.empty:
        st.markdown("#### Strain trend over time")
        fig = px.line(rows, x='created_at', y='total_score', markers=True, labels={'created_at': 'Check-in', 'total_score': 'Strain score (0-20)'})
        fig.update_yaxes(range=[0, 20])
        st.plotly_chart(fig, use_container_width=True)


