        execute('INSERT INTO adv_sleep (patient_id, log_date, bedtime, wake_time, night_awakenings, restlessness, notes, created_at) VALUES (?,?,?,?,?,?,?,?)',
                (pid, str(d), bedtime.strftime('%H:%M'), wake.strftime('%H:%M'), int(awakenings), restlessness, notes.strip(), now_text()))
