_ALARM_NOTE_FREQS = {
    "C4":261.63,"D4":293.66,"E4":329.63,"F4":349.23,"G4":392.00,"A4":440.00,"B4":493.88,
    "C5":523.25,"D5":587.33,"E5":659.25,"F5":698.46,"G5":783.99,"A5":880.00,"B5":987.77,"C6":1046.50,
}

def build_alarm_music_library():
    """Builds 100 distinct generated alarm melodies (no external audio files needed).
    Each entry is a named short tune made of a few tones, so every option actually
    sounds different from the others."""
    adjectives = ["Gentle","Soft","Calm","Bright","Warm","Peaceful","Cheerful","Sweet","Quiet","Joyful"]
    nouns = ["Bells","Chimes","Melody","Harp","Piano","Breeze","Birdsong","Lullaby","Serenade","Tune"]
    names = [f"{a} {n}" for a in adjectives for n in nouns]  # 10 x 10 = 100 unique names
    note_names = list(_ALARM_NOTE_FREQS.keys())
    library = []
    for i, name in enumerate(names):
        start = i % len(note_names)
        length = 5 + (i % 3)          # vary tune length: 5, 6 or 7 notes
        shape = i % 3                  # vary the melodic shape
        if shape == 0:                 # ascending
            idxs = [(start + j) % len(note_names) for j in range(length)]
        elif shape == 1:                # descending
            idxs = [(start - j) % len(note_names) for j in range(length)]
        else:                           # up-and-down
            half = length // 2
            idxs = [(start + j) % len(note_names) for j in range(half)] + \
                   [(start + half - j) % len(note_names) for j in range(half + 1)]
        notes = [_ALARM_NOTE_FREQS[note_names[k]] for k in idxs]
        library.append({"id": i + 1, "name": name, "notes": notes})
    return library

ALARM_MUSIC_LIBRARY = build_alarm_music_library()
ALARM_MUSIC_NAMES = [m["name"] for m in ALARM_MUSIC_LIBRARY]
ALARM_MUSIC_LOOKUP = {m["name"]: m["notes"] for m in ALARM_MUSIC_LIBRARY}


def _alarm_html(alarm_rows):
    """Browser-side alarm scheduler. It keeps running while the page is open.
    No song name is required to set an alarm - the patient/caregiver simply
    picks one of 100 built-in alarm music options, each with its own short
    generated tune. An optional direct audio URL can still be supplied to
    override the tune with real audio playback.
    """
    payload = json.dumps([
        {"time": r["alarm_time"], "title": r["title"], "song": r["song_name"],
         "notes": ALARM_MUSIC_LOOKUP.get(r["song_name"], [523.25,659.25,783.99,1046.5,783.99,659.25]),
         "url": r.get("audio_url", ""), "id": int(r["id"])}
        for _, r in alarm_rows.iterrows()
    ]) if not alarm_rows.empty else "[]"
    return f"""
    <div style='padding:12px;border-radius:18px;border:1px solid #ddd;background:#fafafa'>
      <b>⏰ Active patient alarms</b><div id='alarm_status' style='margin-top:8px'>Checking…</div>
    </div>
    <script>
    (() => {{
      const alarms = {payload};
      const status = document.getElementById('alarm_status');
      const fired = {{}};
      function musicalAlarm(song, url, notes) {{
        try {{
          if (url) {{ const audio = new Audio(url); audio.volume = 1.0; audio.play().catch(()=>{{}}); }}
          const C = window.AudioContext || window.webkitAudioContext;
          if(!C) return;
          const ctx = new C();
          const tune = (notes && notes.length) ? notes : [523.25,659.25,783.99,1046.5,783.99,659.25];
          tune.forEach((f,i)=>{{
            const o=ctx.createOscillator(), g=ctx.createGain();
            o.frequency.value=f; o.type='sine';
            g.gain.setValueAtTime(0.0001,ctx.currentTime+i*0.22);
            g.gain.exponentialRampToValueAtTime(0.22,ctx.currentTime+i*0.22+0.03);
            g.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+i*0.22+0.20);
            o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*0.22);o.stop(ctx.currentTime+i*0.22+0.21);
          }});
          if('speechSynthesis' in window) {{ const u=new SpeechSynthesisUtterance('Reminder: '+song); u.rate=.78; speechSynthesis.speak(u); }}
        }} catch(e) {{}}
      }}
      function check() {{
        const d=new Date(), hh=String(d.getHours()).padStart(2,'0'), mm=String(d.getMinutes()).padStart(2,'0');
        const now=hh+':'+mm;
        const active=alarms.filter(a=>a.time===now);
        if(active.length) active.forEach(a=>{{ const k=a.id+'-'+d.toDateString()+'-'+now; if(!fired[k]){{ fired[k]=true; musicalAlarm(a.song, a.url, a.notes); alert('⏰ '+a.title+'\\n🎵 '+a.song); }} }});
        status.innerHTML = active.length ? '🔔 Alarm due now — '+active.map(a=>a.title).join(', ') : ('Next check: '+now+' • '+alarms.length+' active alarm(s)');
      }}
      check(); setInterval(check,1000);
    }})();
    </script>"""


