def ai_doctor_page():
    pid=patient["id"]; name=patient.get("name") or "friend"
    st.markdown("## 🩺 AI Doctor — Advanced Conversational Companion")
    st.markdown("""
    <div class='doctor-avatar-wrap'><div class='doctor-avatar-ring'><div class='doctor-avatar'>🧑‍⚕️</div></div></div>
    <div class='hero'><h2>Hello! I'm here to talk with you.</h2><p>I can discuss symptoms, memory concerns, routines, wellness, appointments and caregiver questions. I am a support tool, not a replacement for a clinician.</p></div>
    """,unsafe_allow_html=True)
    chat=get_doctor_chat(pid)
    for _,r in chat.iterrows():
        who="You" if r["role"]=="patient" else "🧑‍⚕️ AI Doctor"
        st.markdown(f"**{who}:** {r['message']}")
    prompt=st.chat_input("Tell the AI Doctor what is happening…")
    if prompt:
        add_doctor_chat(pid,"patient",prompt)
        current=get_doctor_chat(pid)
        try:
            reply=generate_doctor_reply(prompt,name,current)
        except Exception:
            reply=generate_doctor_reply_offline(prompt,name)
        add_doctor_chat(pid,"doctor",reply)
        execute("INSERT INTO ultra_ai_sessions (patient_id,session_type,summary,created_at) VALUES (?,?,?,?)",(pid,"AI Doctor",prompt[:500],now_text()))
        st.rerun()
    c1,c2,c3=st.columns(3)
    with c1:
        if st.button("🔊 Read latest reply aloud") and not chat.empty: speak(chat.iloc[-1]["message"])
    with c2:
        if st.button("🧠 Start memory conversation"):
            add_doctor_chat(pid,"doctor","Let's gently explore a familiar memory. What place from your younger years comes to mind first?"); st.rerun()
    with c3:
        if st.button("🧹 Clear doctor conversation"): clear_doctor_chat(pid); st.rerun()
    st.warning("If there are emergency symptoms such as severe chest pain, trouble breathing, stroke signs, unconsciousness or severe bleeding, seek emergency medical help immediately.")


